def findTotal(text: String): Either[String, String] = {
  val lines = text.split("
")
  for (i <- lines.indices) {
    if (lines(i).contains("object Orders") && lines(i).contains("def total")) {
      val start = lines(i).indexOf("def total") + 9
      val end = lines(i).lastIndexOf("}") + 1
      val definition = lines(i).substring(start, end)
      return Right(definition)
    }
  }
  Left("Could not find 'def total' inside 'object Orders' in the provided text.")
}

