def process(command: List[String], dir: Path, timeoutMs: Long): Either[String, Ran] = {
  val result = Exec.run[Ran](command, dir, timeoutMs)
  result match {
    case Left(err) => Left(err)
    case Right(ran) => Right(ran)
  }
}

