def findTotal(text: String): Either[String, String] = {
  val header = Equivalence.header(text)
  val target = Equivalence.target(ix, header.head)
  val definition = Equivalence.definitionIn(text, "object Orders", "total")
  definition.flatMap { defText =>
    if (Equivalence.impure.exists(s => s.startsWith(defText))) {
      Right(defText)
    } else {
      Left("No impure symbol found in definition")
    }
  }
}

