import java.nio.file.Path

object Tasty {
  def classDirOf(root: Path): Path = {
    val fileName = root.fileName
    val prefix = if (fileName.startsWith("test-")) "test-" else ""
    val suffix = if (fileName.startsWith("test-")) "test-classes" else "classes"
    val newFileName = s"${prefix}classes"
    val newRoot = root.resolveSibling(newFileName)
    if (newRoot.exists()) newRoot else root.resolve("classes")
  }
}

